#include <bits/stdc++.h>
#define endl '\n'
using namespace std;

const int N = 10;
const int INF = 1000000000;

string g[N];
int n_scientists[N][N] = {};
int n_rescue[N][N] = {};
int infect_time[N][N] = {};
int di[] = {-1, 1, 0, 0};
int dj[] = {0, 0, -1, 1};
int reach_time[N][N][N][N] = {};

struct Dinic {
    struct Edge {
        int to, rev, cap;
    };
    vector<vector<Edge>> g;
    vector<int> level, iter;
    Dinic(int n) : g(n), level(n), iter(n) {}
    void add_edge(int from, int to, int cap) {
        g[from].push_back({to, (int)g[to].size(), cap});
        g[to].push_back({from, (int)g[from].size() - 1, 0});
    }
    void bfs(int s) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (const Edge &e : g[v]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
    }
    int dfs(int v, int t, int f) {
        if (v == t) return f;
        for (int &i = iter[v]; i < (int)g[v].size(); ++i) {
            Edge &e = g[v][i];
            if (e.cap > 0 && level[e.to] == level[v] + 1) {
                int ret = dfs(e.to, t, min(f, e.cap));
                if (ret > 0) {
                    e.cap -= ret;
                    g[e.to][e.rev].cap += ret;
                    return ret;
                }
            }
        }
        return 0;
    }
    int max_flow(int s, int t) {
        int flow = 0;
        while (true) {
            bfs(s);
            if (level[t] == -1) break;
            fill(iter.begin(), iter.end(), 0);
            int f;
            while ((f = dfs(s, t, INF)) > 0) flow += f;
        }
        return flow;
    }
};

int node_id(int n, int i, int j, bool right) {
    return i * n + j + (right ? n * n : 0);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, t;
    cin >> n >> t;

    pair<int,int> explode;
    string line;
    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] == 'Y') {
                g[i][j] = 'Y';
            } else if (line[j] == 'Z') {
                g[i][j] = 'Z';
                explode = {i, j};
            } else {
                g[i][j] = '.';
                n_scientists[i][j] += line[j] - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] != 'Y' && line[j] != 'Z') {
                n_rescue[i][j] += line[j] - '0';
            }
        }
    }

    memset(infect_time, -1, sizeof(infect_time));
    infect_time[explode.first][explode.second] = 0;
    queue<pair<int,int>> q;
    q.push(explode);
    while (!q.empty()) {
        int i = q.front().first, j = q.front().second;
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int ni = i + di[d], nj = j + dj[d];
            if (0 <= ni && ni < n && 0 <= nj && nj < n && g[ni][nj] == '.' && infect_time[ni][nj] == -1) {
                infect_time[ni][nj] = infect_time[i][j] + 1;
                q.push({ni, nj});
            }
        }
    }

    memset(reach_time, -1, sizeof(reach_time));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (g[i][j] == '.') {
                reach_time[i][j][i][j] = 0;
                queue<pair<int,int>> q;
                q.push({i, j});
                while (!q.empty()) {
                    int ii = q.front().first, jj = q.front().second;
                    q.pop();
                    if (infect_time[ii][jj] == -1 || reach_time[i][j][ii][jj] < infect_time[ii][jj]) {
                        for (int d = 0; d < 4; ++d) {
                            int ni = ii + di[d], nj = jj + dj[d];
                            if (0 <= ni && ni < n && 0 <= nj && nj < n && g[ni][nj] == '.'
                                && (infect_time[ni][nj] == -1 || reach_time[i][j][ii][jj] + 1 <= infect_time[ni][nj])
                                && reach_time[i][j][ni][nj] == -1) {
                                reach_time[i][j][ni][nj] = reach_time[i][j][ii][jj] + 1;
                                q.push({ni, nj});
                            }
                        }
                    }
                }
            }
        }
    }

    int src = 2 * n * n;
    int sink = src + 1;
    Dinic dinic(2 * n * n + 2);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (n_scientists[i][j]) {
                dinic.add_edge(src, node_id(n, i, j, false), n_scientists[i][j]);
            }
            if (n_rescue[i][j]) {
                dinic.add_edge(node_id(n, i, j, true), sink, n_rescue[i][j]);
            }
            for (int ii = 0; ii < n; ++ii) {
                for (int jj = 0; jj < n; ++jj) {
                    if (0 <= reach_time[i][j][ii][jj] && reach_time[i][j][ii][jj] <= t) {
                        dinic.add_edge(node_id(n, i, j, false), node_id(n, ii, jj, true), INF);
                    }
                }
            }
        }
    }

    cout << dinic.max_flow(src, sink) << endl;
    return 0;
}
